function formatDate(dateStr) {
  if (!dateStr || typeof dateStr !== 'string') return null;

  const parts = dateStr.trim().split(/[\/-]/);
  if (parts.length === 3) {
    const [day, month, year] = parts;
    if (day.length === 2 && month.length === 2 && year.length === 4) {
      return `${year}-${month}-${day}`;
    }
  }
  return null;
}

const items = $input.all();
const output = [];

items.forEach((item) => {
  const data = item.json;
  const symbol = data.stockSymbol || data.code;
  const events = data.corporateEvents;

  if (!symbol || !Array.isArray(events) || events.length === 0) {
    return;
  }

  events.forEach((event) => {
    output.push({
      symbol: symbol,
      event_type: event.eventListCode || null,
      description: event.eventTitle || null,
      ex_rights_date: formatDate(event.exrightDate),
      record_date: formatDate(event.recordDate),
      payment_date: formatDate(event.exerciseDate),
    });
  });
});

return output;

// Extract text content from binary file property
const binaryPropertyName = 'file'; // Change to match your binary property name

if (!items[0].binary || !items[0].binary[binaryPropertyName]) {
  throw new Error(`Binary property "${binaryPropertyName}" not found in input.`);
}

// Convert base64 data to string
const base64Data = items[0].binary[binaryPropertyName].data;
const jsonText = Buffer.from(base64Data, 'base64').toString('utf-8');

// Parse string to JSON object
const parsedData = JSON.parse(jsonText);

return {
  json: parsedData
};

const rawData = $input.first().json;

let stockList = [];
if (rawData.data && Array.isArray(rawData.data)) {
  stockList = rawData.data;
} else if (Array.isArray(rawData) && rawData[0]?.data) {
  stockList = rawData[0].data;
}

return stockList
  .filter(item => Array.isArray(item.corporateEvents) && item.corporateEvents.length > 0)
  .map(item => ({
    json: {
      stockSymbol: item.stockSymbol,
      corporateEvents: item.corporateEvents
    }
  }));
